import type { Curriculum } from './types';

// Eagerly bundles every file generated by scripts/generate-curriculum.mjs —
// same import.meta.glob pattern loadData.ts uses for data/processed/*.json.
// Re-run that script and drop a new file in and it shows up automatically.
const modules = import.meta.glob('../../../data/curriculum/official/*.json', {
  eager: true,
  import: 'default',
}) as Record<string, unknown>;

const officialCurricula: Curriculum[] = Object.entries(modules)
  .filter(([filePath]) => !filePath.endsWith('_summary.json'))
  .map(([, mod]) => mod as Curriculum);

const byMartialArt = new Map(officialCurricula.map((c) => [c.martialArt, c]));
const byId = new Map(officialCurricula.map((c) => [c.id, c]));

export function getOfficialCurriculum(martialArt: string): Curriculum | undefined {
  return byMartialArt.get(martialArt);
}

export function getOfficialCurriculumById(id: string): Curriculum | undefined {
  return byId.get(id);
}

export function listOfficialCurricula(): Curriculum[] {
  return officialCurricula;
}
